/**
 * Minimal i18n: twenty languages — English (default), Japanese,
 * Simplified Chinese, Korean, Spanish, Turkish, Persian, Indonesian,
 * Vietnamese, Thai, Italian, Portuguese, Dutch, Polish, Ukrainian,
 * German, Russian, Arabic, Hindi, French (Thai, Italian, Polish,
 * Ukrainian, German, Russian and Arabic added in v0.5.0). Plain
 * everyday words only; no jargon on screen, in every language.
 *
 * Persian (fa) and Arabic (ar) are right-to-left languages: when
 * one is the active language the whole layout mirrors (see
 * src/lib/rtl.ts, which drives I18nManager from langIsRtl
 * below). All other languages are left-to-right.
 *
 * The current language lives in a module-level variable (set by
 * AppContext) so plain library code can translate too, mirroring
 * the GuppyWallet pattern.
 */
export type Lang =
  | 'en' | 'ja' | 'zh' | 'ko' | 'es' | 'tr' | 'fa'
  | 'id' | 'vi' | 'th' | 'it' | 'pt' | 'nl' | 'pl'
  | 'uk' | 'de' | 'ru' | 'ar' | 'hi' | 'fr';

export const LANGS: { code: Lang; label: string }[] = [
  { code: 'en', label: 'English' },
  { code: 'ja', label: '日本語' },
  { code: 'zh', label: '简体中文' },
  { code: 'ko', label: '한국어' },
  { code: 'es', label: 'Español' },
  { code: 'tr', label: 'Türkçe' },
  { code: 'fa', label: 'فارسی' },
  { code: 'id', label: 'Bahasa Indonesia' },
  { code: 'vi', label: 'Tiếng Việt' },
  { code: 'th', label: 'ภาษาไทย' },
  { code: 'it', label: 'Italiano' },
  { code: 'pt', label: 'Português' },
  { code: 'nl', label: 'Nederlands' },
  { code: 'pl', label: 'Polski' },
  { code: 'uk', label: 'Українська' },
  { code: 'de', label: 'Deutsch' },
  { code: 'ru', label: 'Русский' },
  { code: 'ar', label: 'العربية' },
  { code: 'hi', label: 'हिन्दी' },
  { code: 'fr', label: 'Français' },
];

export function isLang(v: unknown): v is Lang {
  return (
    v === 'en' || v === 'ja' || v === 'zh' || v === 'ko' || v === 'es' ||
    v === 'tr' || v === 'fa' || v === 'id' || v === 'vi' || v === 'th' ||
    v === 'it' || v === 'pt' || v === 'nl' || v === 'pl' || v === 'uk' ||
    v === 'de' || v === 'ru' || v === 'ar' || v === 'hi' || v === 'fr'
  );
}

/** True for languages written right-to-left (Persian, Arabic). */
export function langIsRtl(l: Lang): boolean {
  return l === 'fa' || l === 'ar';
}

/** BCP-47 locale per language, for date formatting. */
export const LOCALES: Record<Lang, string> = {
  en: 'en-US',
  ja: 'ja-JP',
  zh: 'zh-CN',
  ko: 'ko-KR',
  es: 'es-ES',
  tr: 'tr-TR',
  fa: 'fa-IR',
  id: 'id-ID',
  vi: 'vi-VN',
  th: 'th-TH',
  it: 'it-IT',
  pt: 'pt-BR',
  nl: 'nl-NL',
  pl: 'pl-PL',
  uk: 'uk-UA',
  de: 'de-DE',
  ru: 'ru-RU',
  ar: 'ar-EG',
  hi: 'hi-IN',
  fr: 'fr-FR',
};

let current: Lang = 'en';
export function setLang(l: Lang): void {
  current = l;
}
export function getLang(): Lang {
  return current;
}

